import { NextRequest, NextResponse } from "next/server";
import { getSubmission } from "@/app/_lib/db";
import { mintObservedFromSubmission, promoteSubmission } from "@/app/_lib/devcase-run";
import { activePromoteFloor } from "@/app/_lib/devcase-orchestrator";
import { recordAudit } from "@/app/_lib/dev-control";

// Bridge: an evaluated submission becomes a pipeline entry + a Decisions review card.
// Shares promoteSubmission with the lifecycle orchestrator.
//
// Trust fix: the manual promote path now enforces the SAME calibration floor the
// orchestrator's ranked stage uses (activePromoteFloor). Previously a reviewer could
// see the UI advise "below floor â€” hold" while this route happily promoted anyway,
// which is exactly the advice/behavior divergence reviewers reported. A human can
// still promote below the floor, but must say so explicitly (override: true), and
// the override is written to the immutable audit log.
export async function POST(request: NextRequest) {
  try {
    const body = (await request.json().catch(() => ({}))) as { submissionId?: string; override?: boolean; reason?: string };
    if (!body.submissionId) return NextResponse.json({ error: "submissionId is required." }, { status: 400 });
    const sub = getSubmission(body.submissionId);
    if (!sub) return NextResponse.json({ error: "submission not found" }, { status: 404 });
    if (!sub.evaluation) return NextResponse.json({ error: "evaluate the submission first." }, { status: 400 });

    const floor = activePromoteFloor();
    const score = typeof sub.evaluation.score === "number" ? sub.evaluation.score : null;
    if (score !== null && score < floor && !body.override) {
      // Advice and behavior now agree: below the floor, the default is HOLD.
      return NextResponse.json(
        {
          error: `submission scored ${score}, below the active promote floor (${floor}). Pass override:true to promote anyway.`,
          floor,
          score,
          overridable: true,
        },
        { status: 409 },
      );
    }

    const entryId = promoteSubmission(body.submissionId);
    // Every manual promotion is auditable â€” especially floor overrides, which are the
    // decisions a calibration review most needs to see.
    recordAudit({
      actor: "human",
      action: score !== null && score < floor ? "promote_override_below_floor" : "promote_manual",
      reason: body.reason ?? (score !== null ? `score ${score} vs floor ${floor}` : "no score on evaluation"),
      ref: body.submissionId,
    });

    // Take-home -> observed bridge (best-effort): a promoted submission cleared the
    // transfer floor, so a resolvable candidate profile gains observed-provenance
    // skills. Failures never block the promotion itself.
    let observedSkills: string[] = [];
    if (entryId) {
      try {
        observedSkills = (await mintObservedFromSubmission(body.submissionId, entryId)).credited;
      } catch {
        /* minting is enrichment, not a gate */
      }
    }
    return NextResponse.json({ ok: true, entryId, observedSkills, floor, score });
  } catch (error) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Promote failed." }, { status: 500 });
  }
}

