// The devcase CLI envelope every run* function below shares: make a temp workdir,
// write the per-call JSON arg files into it + build the argv, spawn
// `python -m pipeline.jobfit.devcase.devcase_cli <verb> â€¦`, fail on a non-zero
// exit (mapping stderr â†’ PipelineError), parse the single JSON line, then always
// clean the workdir up.
async function runDevcaseCli<T>(
  build: (workdir: string) => string[] | Promise<string[]>,
  signal?: AbortSignal,
): Promise<T> {
  const workdir = await createWorkdir();
  try {
    const args = await build(workdir);
    const { result } = spawnPython(["-m", "pipeline.jobfit.devcase.devcase_cli", ...args], { signal, env: buildLlmConfigEnv() });
    const { stdout, stderr, exitCode } = await result;
    if (exitCode !== 0) throw new PipelineError(parseStderrError(stderr, exitCode));
    return parsePythonJson<T>(stdout, stderr);
  } finally {
    await cleanupWorkdir(workdir);
  }
}

// NOTE: promoteSubmission itself is intentionally left floor-agnostic â€” it performs the
// mechanical bridge (submission -> pipeline entry + review card). Floor policy is the
// caller's concern: the orchestrator's ranked stage checks activePromoteFloor() before
// calling it, and the manual promote route now does the same. Keeping policy out of the
// mechanism means both callers share one floor source and one bridge implementation.

// â€¦ rest of file unchanged (need analysis, design artifacts, evaluate, seed
