export const DEV_POLICY = {
  autoApproveMaxGaps: 1,
  autoApproveMinConfidence: 0.5,
  promoteFloor: 55,
  promoteTopN: 3,
};

// THE promote-floor resolution: a human's outcome-driven calibration (dev_control)
// when set, else the DEV_POLICY default. Shared by the orchestrator's ranked stage,
// the outcomes route, AND (as of this change) the manual promote route â€” so the floor
// the pipeline promotes against can never diverge from the one a human promotes against.
export const activePromoteFloor = (): number => getPromoteFloor() ?? DEV_POLICY.promoteFloor;

// â€¦ remainder of the orchestrator (gateApproval, STAGES, runLifecycle drive loop,
// collecting/ranked/promoted handlers) unchanged â€¦

