// floor store and recordAudit() the immutable decision log â€” the fix consumes these,
// it does not need to change them.

import Database from "better-sqlite3";
import { openStore } from "./db-path";

let _db: Database.Database | null = null;
function db(): Database.Database {
  if (_db) return _db;
  const d = openStore();
  d.exec(`
    CREATE TABLE IF NOT EXISTS dev_audit (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lifecycle_id TEXT,
      actor TEXT NOT NULL,
      action TEXT NOT NULL,
      reason TEXT,
      ref TEXT,
      created_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_dev_audit_created ON dev_audit (id DESC);
    CREATE TABLE IF NOT EXISTS dev_control (key TEXT PRIMARY KEY, value TEXT);
  `);
  _db = d;
  return d;
}

export type Actor = "auto" | "human" | "system";
export type AuditEvent = {
  id: number;
  lifecycleId: string | null;
  actor: string;
  action: string;
  reason: string | null;
  ref: string | null;
  createdAt: string;
};

export function recordAudit(input: { lifecycleId?: string | null; actor: Actor; action: string; reason?: string; ref?: string }): void {
  try {
    db()
      .prepare(`INSERT INTO dev_audit (lifecycle_id, actor, action, reason, ref, created_at) VALUES (?, ?, ?, ?, ?, ?)`)
      .run(input.lifecycleId ?? null, input.actor, input.action, input.reason ?? null, input.ref ?? null, new Date().toISOString());
  } catch {
    /* audit must never break the pipeline */
  }
}

export function listAudit(limit = 80): AuditEvent[] {
  const rows = db().prepare(`SELECT * FROM dev_audit ORDER BY id DESC LIMIT ?`).all(limit) as Array<Record<string, unknown>>;
  return rows.map((r) => ({
    id: r.id as number,
    lifecycleId: (r.lifecycle_id as string) ?? null,
    actor: r.actor as string,
    action: r.action as string,
    reason: (r.reason as string) ?? null,
    ref: (r.ref as string) ?? null,
    createdAt: r.created_at as string,
  }));
}

export type Autonomy = "on" | "paused";

export function getAutonomy(): Autonomy {
  const r = db().prepare(`SELECT value FROM dev_control WHERE key = 'autonomy'`).get() as { value?: string } | undefined;
  return r?.value === "paused" ? "paused" : "on";
}

export function setAutonomy(value: Autonomy): void {
  db().prepare(`INSERT INTO dev_control (key, value) VALUES ('autonomy', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(value);
}

export function getPromoteFloor(): number | null {
  const r = db().prepare(`SELECT value FROM dev_control WHERE key = 'promote_floor'`).get() as { value?: string } | undefined;
  const n = Number(r?.value);
  return Number.isFinite(n) ? n : null;
}

export function setPromoteFloor(value: number): void {
  if (!Number.isFinite(value)) throw new Error("promote floor must be a finite number");
  const v = String(Math.max(0, Math.min(100, Math.round(value))));
  db().prepare(`INSERT INTO dev_control (key, value) VALUES ('promote_floor', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(v);
}

import { describe, expect, it, vi, beforeEach } from "vitest";

// Verification for the promote-path trust fix. The manual route must now agree with
// the orchestrator's advice: below the active floor -> 409 hold (unless an explicit
// human override), at/above the floor -> promote as before.

const getSubmission = vi.fn();
const promoteSubmission = vi.fn(() => "entry-1");
const mintObservedFromSubmission = vi.fn(async () => ({ credited: ["react"] }));
const activePromoteFloor = vi.fn(() => 55);
const recordAudit = vi.fn();

vi.mock("@/app/_lib/db", () => ({ getSubmission }));
vi.mock("@/app/_lib/devcase-run", () => ({ promoteSubmission, mintObservedFromSubmission }));
vi.mock("@/app/_lib/devcase-orchestrator", () => ({ activePromoteFloor }));
vi.mock("@/app/_lib/dev-control", () => ({ recordAudit }));

import { POST } from "./route";

const req = (body: unknown) => ({ json: async () => body }) as never;

beforeEach(() => {
  vi.clearAllMocks();
  activePromoteFloor.mockReturnValue(55);
});

describe("manual promote route respects the calibration floor", () => {
  it("holds a below-floor submission with 409 and does not promote", async () => {
    getSubmission.mockReturnValue({ evaluation: { score: 40 } });
    const res = await POST(req({ submissionId: "s1" }));
    expect(res.status).toBe(409);
    expect(promoteSubmission).not.toHaveBeenCalled();
  });

  it("promotes at/above the floor exactly as before", async () => {
    getSubmission.mockReturnValue({ evaluation: { score: 72 } });
    const res = await POST(req({ submissionId: "s1" }));
    expect(res.status).toBe(200);
    expect(promoteSubmission).toHaveBeenCalledWith("s1");
    expect(recordAudit).toHaveBeenCalledWith(expect.objectContaining({ action: "promote_manual" }));
  });

  it("allows an explicit human override below the floor and audits it", async () => {
    getSubmission.mockReturnValue({ evaluation: { score: 40 } });
    const res = await POST(req({ submissionId: "s1", override: true, reason: "strong live session" }));
    expect(res.status).toBe(200);
    expect(recordAudit).toHaveBeenCalledWith(expect.objectContaining({ action: "promote_override_below_floor" }));
  });

  it("reads the calibrated floor, not the static default", async () => {
    activePromoteFloor.mockReturnValue(70);
    getSubmission.mockReturnValue({ evaluation: { score: 60 } });
    const res = await POST(req({ submissionId: "s1" }));
    expect(res.status).toBe(409);
  });

  it("promotes unscored evaluations (no score -> no floor check) unchanged", async () => {
    getSubmission.mockReturnValue({ evaluation: {} });
    const res = await POST(req({ submissionId: "s1" }));
    expect(res.status).toBe(200);
  });
});
